<?php
if(!defined('ABSPATH'))exit;
function dgs_study_tables(){global $wpdb;return array('days'=>$wpdb->prefix.'dgs_study_days','entries'=>$wpdb->prefix.'dgs_study_entries','feedback'=>$wpdb->prefix.'dgs_study_feedback');}
add_action('init',function(){if(get_option('dgs_study_schema')==='1')return;global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$t=dgs_study_tables();$cc=$wpdb->get_charset_collate();
 dbDelta("CREATE TABLE {$t['days']} (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 student_id bigint(20) unsigned NOT NULL,
 school_year varchar(9) NOT NULL,
 school_day date NOT NULL,
 minutes smallint unsigned NOT NULL DEFAULT 0,
 entry_count smallint unsigned NOT NULL DEFAULT 0,
 PRIMARY KEY  (id),
 UNIQUE KEY student_day (student_id,school_year,school_day)
 ) ENGINE=InnoDB $cc;");
 dbDelta("CREATE TABLE {$t['entries']} (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 day_id bigint(20) unsigned NOT NULL,
 student_id bigint(20) unsigned NOT NULL,
 school_year varchar(9) NOT NULL,
 school_day date NOT NULL,
 class_id bigint(20) unsigned NOT NULL,
 subject_id bigint(20) unsigned NOT NULL,
 minutes smallint unsigned NOT NULL,
 note varchar(1000) NOT NULL DEFAULT '',
 created_at datetime NOT NULL,
 updated_at datetime NOT NULL,
 revision bigint(20) unsigned NOT NULL DEFAULT 1,
 request_token varchar(36) NOT NULL,
 PRIMARY KEY  (id),
 UNIQUE KEY request_token (request_token),
 KEY student_year_day (student_id,school_year,school_day)
 ) ENGINE=InnoDB $cc;");
 dbDelta("CREATE TABLE {$t['feedback']} (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 student_id bigint(20) unsigned NOT NULL,
 counselor_id bigint(20) unsigned NOT NULL,
 school_year varchar(9) NOT NULL,
 message text NOT NULL,
 revision bigint(20) unsigned NOT NULL DEFAULT 1,
 updated_at datetime NOT NULL,
 PRIMARY KEY  (id),
 UNIQUE KEY student_counselor_year (student_id,counselor_id,school_year)
 ) ENGINE=InnoDB $cc;");
 foreach($t as $table)if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($table)))!==$table)return;update_option('dgs_study_schema','1',false);
},16);
function dgs_study_assigned($student,$year,$counselor=0){global $wpdb;$e=dgs_edu_tables();return (bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM {$e['counseling']} WHERE student_id=%d AND school_year=%s AND counselor_id=%d",$student,$year,$counselor?:get_current_user_id()));}
function dgs_study_can_read($student,$year){if(!is_user_logged_in()||!dgs_edu_year($year)||!dgs_edu_role($student,'dgs_student'))return false;if(current_user_can('dgs_manage_education'))return true;$uid=get_current_user_id();return (dgs_edu_role($uid,'dgs_student')&&$uid===(int)$student)||(dgs_edu_role($uid,'dgs_counselor')&&dgs_study_assigned($student,$year));}
function dgs_study_subjects($class){if(!$class)return array();global $wpdb;$e=dgs_edu_tables();$rows=$wpdb->get_results($wpdb->prepare("SELECT s.id,s.title FROM {$e['subjects']} s JOIN {$e['teaching']} a ON a.subject_id=s.id WHERE a.class_id=%d AND s.active=1 ORDER BY s.title",$class));$out=array();foreach($rows as $s)$out[$s->id]=$s->title;return $out;}
function dgs_study_save($d){
 if(!dgs_edu_role(get_current_user_id(),'dgs_student')||current_user_can('dgs_manage_education'))return dgs_edu_error('access','فقط دانش‌آموز می‌تواند مطالعه خودش را ثبت کند.');foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','درخواست معتبر نیست.');if(get_option('dgs_study_schema')!=='1')return dgs_edu_error('schema','جدول مطالعه آماده نیست.');$year=dgs_edu_year((string)($d['year']??''));$today=dgs_att_today();if(!$year||dgs_att_parse_day(dgs_att_jdate($today),$year)!==$today||($d['day']??'')!==$today)return dgs_edu_error('day','ثبت و ویرایش فقط برای امروز و سال تحصیلی مربوط امکان‌پذیر است؛ صفحه را تازه کنید.');$op=(string)($d['operation']??'');if(!in_array($op,array('create','edit','delete'),true))return dgs_edu_error('operation','عملیات معتبر نیست.');$uid=get_current_user_id();global $wpdb;$t=dgs_study_tables();$old=null;$id=absint($d['entry_id']??0);
 if($op!=='create'){$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['entries']} WHERE id=%d AND student_id=%d AND school_year=%s AND school_day=%s",$id,$uid,$year,$today));if(!$old||!ctype_digit((string)($d['revision']??''))||(int)$d['revision']!==(int)$old->revision)return dgs_edu_error('stale','رکورد متعلق به شما نیست یا تغییر کرده است؛ صفحه را تازه کنید.');}
 $minutes=0;$subject=0;$note='';$class=null;if($op!=='delete'){$class=dgs_hw_student_class($year);$subjects=$class&&$class->active?dgs_study_subjects($class->id):array();$subject=absint($d['subject_id']??0);$h=dgs_edu_digits((string)($d['hours']??''));$m=dgs_edu_digits((string)($d['minutes']??''));$note=sanitize_textarea_field((string)($d['note']??''));if(!isset($subjects[$subject])||!ctype_digit($h)||!ctype_digit($m)||(int)$h>24||(int)$m>59||dgs_edu_length($note)>1000)return dgs_edu_error('fields','درس مجاز، زمان و یادداشت تا ۱۰۰۰ نویسه وارد کنید.');$minutes=(int)$h*60+(int)$m;if($minutes<1||$minutes>1440)return dgs_edu_error('time','مدت مطالعه بین یک دقیقه و ۲۴ ساعت باشد.');}
 $token=(string)($d['request_token']??'');if($op==='create'){if(!preg_match('/^[a-f0-9-]{36}$/D',$token))return dgs_edu_error('token','فرم را تازه کنید.');$prior=$wpdb->get_row($wpdb->prepare("SELECT student_id,school_year FROM {$t['entries']} WHERE request_token=%s",$token));if($prior)return (int)$prior->student_id===$uid&&$prior->school_year===$year?'این مطالعه قبلاً ثبت شده است.':dgs_edu_error('token','فرم معتبر نیست.');}
 $wpdb->query('START TRANSACTION');if($op==='create'){$ok=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$t['days']} (student_id,school_year,school_day,minutes,entry_count) VALUES (%d,%s,%s,0,0)",$uid,$year,$today));if($ok===false){$wpdb->query('ROLLBACK');return dgs_edu_error('write','ذخیره انجام نشد.');}$day=$wpdb->get_row($wpdb->prepare("SELECT id FROM {$t['days']} WHERE student_id=%d AND school_year=%s AND school_day=%s",$uid,$year,$today));if(!$day){$wpdb->query('ROLLBACK');return dgs_edu_error('write','ذخیره روز انجام نشد.');}$day_id=$day->id;$ok=$wpdb->insert($t['entries'],array('day_id'=>$day_id,'student_id'=>$uid,'school_year'=>$year,'school_day'=>$today,'class_id'=>$class->id,'subject_id'=>$subject,'minutes'=>$minutes,'note'=>$note,'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql'),'revision'=>1,'request_token'=>$token));}
 else{$day_id=$old->day_id;if($op==='delete')$ok=$wpdb->query($wpdb->prepare("DELETE FROM {$t['entries']} WHERE id=%d AND student_id=%d AND revision=%d",$id,$uid,$old->revision));else $ok=$wpdb->query($wpdb->prepare("UPDATE {$t['entries']} SET subject_id=%d,class_id=%d,minutes=%d,note=%s,revision=revision+1,updated_at=%s WHERE id=%d AND student_id=%d AND revision=%d",$subject,$class->id,$minutes,$note,current_time('mysql'),$id,$uid,$old->revision));}
 if($ok!==1){$wpdb->query('ROLLBACK');return dgs_edu_error('stale','ذخیره انجام نشد یا رکورد هم‌زمان تغییر کرده؛ صفحه را تازه کنید.');}$delta=$minutes-($old?(int)$old->minutes:0);$count=$op==='create'?1:($op==='delete'?-1:0);$ok=$wpdb->query($wpdb->prepare("UPDATE {$t['days']} SET minutes=minutes+(%d),entry_count=entry_count+(%d) WHERE id=%d AND minutes+(%d) BETWEEN 0 AND 1440 AND entry_count+(%d) BETWEEN 0 AND 100",$delta,$count,$day_id,$delta,$count));if($ok===false||($ok!==1&&($delta!==0||$count!==0))){$wpdb->query('ROLLBACK');return dgs_edu_error('limit','مجموع روز از ۲۴ ساعت یا تعداد ثبت‌ها از ۱۰۰ بیشتر نشود.');}$wpdb->query('COMMIT');return $op==='delete'?'مطالعه حذف شد.':($op==='edit'?'مطالعه ویرایش شد.':'مطالعه ذخیره شد.');
}
function dgs_study_days($student,$year,$from,$to){if(!dgs_study_can_read($student,$year))return array();global $wpdb;$t=dgs_study_tables();return $wpdb->get_results($wpdb->prepare("SELECT school_day,minutes FROM {$t['days']} WHERE student_id=%d AND school_year=%s AND school_day BETWEEN %s AND %s AND minutes>0 ORDER BY school_day",$student,$year,$from,$to),OBJECT_K);}
function dgs_study_entries($student,$year,$from,$to){if(!dgs_study_can_read($student,$year))return array();global $wpdb;$t=dgs_study_tables();$e=dgs_edu_tables();return $wpdb->get_results($wpdb->prepare("SELECT a.*,s.title AS subject FROM {$t['entries']} a LEFT JOIN {$e['subjects']} s ON s.id=a.subject_id WHERE a.student_id=%d AND a.school_year=%s AND a.school_day BETWEEN %s AND %s ORDER BY a.school_day DESC,a.created_at DESC,a.id DESC LIMIT 200",$student,$year,$from,$to));}
function dgs_study_feedback($student,$year){if(!dgs_study_can_read($student,$year))return null;global $wpdb;$t=dgs_study_tables();$e=dgs_edu_tables();return $wpdb->get_row($wpdb->prepare("SELECT f.*,u.display_name AS counselor FROM {$t['feedback']} f JOIN {$e['counseling']} a ON a.student_id=f.student_id AND a.school_year=f.school_year AND a.counselor_id=f.counselor_id JOIN {$wpdb->users} u ON u.ID=f.counselor_id WHERE f.student_id=%d AND f.school_year=%s",$student,$year));}
function dgs_study_feedback_save($d){foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','درخواست معتبر نیست.');$student=absint($d['student_id']??0);$year=dgs_edu_year((string)($d['year']??''));if(!dgs_edu_role(get_current_user_id(),'dgs_counselor')||!$year||!dgs_study_assigned($student,$year)||!dgs_study_can_read($student,$year))return dgs_edu_error('access','فقط مشاور فعلی این دانش‌آموز اجازه ثبت بازخورد دارد.');$message=sanitize_textarea_field((string)($d['message']??''));$rev=(string)($d['revision']??'');if(!$message||dgs_edu_length($message)>4000||!ctype_digit($rev))return dgs_edu_error('message','بازخورد بین ۱ تا ۴۰۰۰ نویسه باشد.');global $wpdb;$t=dgs_study_tables();$old=dgs_study_feedback($student,$year);if((int)$rev!==($old?(int)$old->revision:0))return dgs_edu_error('stale','بازخورد تغییر کرده؛ صفحه را تازه کنید.');$uid=get_current_user_id();$e=dgs_edu_tables();if($old)$ok=$wpdb->query($wpdb->prepare("UPDATE {$t['feedback']} SET message=%s,updated_at=%s,revision=revision+1 WHERE id=%d AND counselor_id=%d AND revision=%d AND EXISTS(SELECT 1 FROM {$e['counseling']} a WHERE a.student_id=%d AND a.counselor_id=%d AND a.school_year=%s)",$message,current_time('mysql'),$old->id,$uid,$old->revision,$student,$uid,$year));else $ok=$wpdb->query($wpdb->prepare("INSERT INTO {$t['feedback']} (student_id,counselor_id,school_year,message,updated_at,revision) SELECT %d,%d,%s,%s,%s,1 WHERE EXISTS(SELECT 1 FROM {$e['counseling']} a WHERE a.student_id=%d AND a.counselor_id=%d AND a.school_year=%s)",$student,$uid,$year,$message,current_time('mysql'),$student,$uid,$year));return $ok===1?'بازخورد ذخیره شد.':dgs_edu_error('write','بازخورد ذخیره نشد؛ صفحه را تازه کنید.');}
function dgs_study_roster($year,$filters=array(),$offset=0,$count=false){if(!current_user_can('dgs_manage_education')&&!dgs_edu_role(get_current_user_id(),'dgs_counselor'))return $count?0:array();global $wpdb;$e=dgs_edu_tables();$args=array($year);$where='';if(!current_user_can('dgs_manage_education')){$where.=" AND EXISTS(SELECT 1 FROM {$e['counseling']} a WHERE a.student_id=u.ID AND a.school_year=en.school_year AND a.counselor_id=%d)";$args[]=get_current_user_id();}if(!empty($filters['grade'])){$where.=' AND c.grade=%d';$args[]=absint($filters['grade']);}if(!empty($filters['class'])){$where.=' AND c.id=%d';$args[]=absint($filters['class']);}if(!empty($filters['search'])){$where.=' AND u.display_name LIKE %s';$args[]='%'.$wpdb->esc_like($filters['search']).'%';}$sql=" FROM {$e['enrollments']} en JOIN {$wpdb->users} u ON u.ID=en.student_id JOIN {$e['classes']} c ON c.id=en.class_id WHERE en.school_year=%s $where";if($count)return (int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*)'.$sql,$args));$args[]=max(0,(int)$offset);return $wpdb->get_results($wpdb->prepare('SELECT u.ID,u.display_name,c.id AS class_id,c.grade,c.field'.$sql.' ORDER BY c.grade,u.display_name,u.ID LIMIT 20 OFFSET %d',$args));}
function dgs_study_student_class($student,$year){if(!dgs_study_can_read($student,$year))return null;global $wpdb;$e=dgs_edu_tables();return $wpdb->get_row($wpdb->prepare("SELECT c.* FROM {$e['classes']} c JOIN {$e['enrollments']} en ON en.class_id=c.id WHERE en.student_id=%d AND en.school_year=%s",$student,$year));}
function dgs_study_tasks($student,$year,$limit=10,$overdue=false){if(!dgs_study_can_read($student,$year))return array();$class=dgs_study_student_class($student,$year);if(!$class)return array();global $wpdb;$t=dgs_hw_tables();$e=dgs_edu_tables();$sql="SELECT a.id,a.title,a.due_at,x.id AS submission_id,x.status,x.submitted_at FROM {$t['tasks']} a LEFT JOIN {$t['submissions']} x ON x.id=(SELECT MAX(z.id) FROM {$t['submissions']} z WHERE z.task_id=a.id AND z.student_id=%d) WHERE a.class_id=%d AND a.school_year=%s AND a.active=1";$args=array($student,$class->id,$year);if($overdue){$sql.=" AND a.due_at<%d AND (x.id IS NULL OR x.status='revision')";$args[]=time();}$sql.=' ORDER BY a.due_at DESC LIMIT %d';$args[]=max(1,min(200,$limit));return $wpdb->get_results($wpdb->prepare($sql,$args));}
function dgs_study_grade_series($student,$year){if(!dgs_study_can_read($student,$year))return array();global $wpdb;$g=dgs_grade_table();$e=dgs_edu_tables();return $wpdb->get_results($wpdb->prepare("SELECT g.period,AVG(g.score) AS average FROM $g g JOIN {$e['classes']} c ON c.id=g.class_id WHERE g.student_id=%d AND c.school_year=%s AND g.published=1 GROUP BY g.period ORDER BY g.period DESC LIMIT 3",$student,$year));}
add_action('admin_post_dgs_study',function(){if(($_SERVER['REQUEST_METHOD']??'')!=='POST'||!is_user_logged_in())wp_die('دسترسی مجاز نیست.','',array('response'=>403));check_admin_referer('dgs_study','dgs_study_nonce');$d=wp_unslash($_POST);$op=is_string($d['operation']??null)?$d['operation']:'';if($op==='feedback'?!dgs_edu_role(get_current_user_id(),'dgs_counselor'):!dgs_edu_role(get_current_user_id(),'dgs_student'))wp_die('دسترسی مجاز نیست.','',array('response'=>403));$result=$op==='feedback'?dgs_study_feedback_save($d):dgs_study_save($d);$year=is_string($d['year']??null)?dgs_edu_year($d['year']):'';$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,array('error'=>is_wp_error($result),'text'=>is_wp_error($result)?$result->get_error_message():$result),300);$args=array('dg_notice'=>$token);if($op==='feedback')$args['study_student']=is_scalar($d['student_id']??null)?absint($d['student_id']):0;wp_safe_redirect(dgs_school_url('study',$year,$args),303);exit;});
